SELECT DISTINCT ON ((bar_start_utc AT TIME ZONE 'UTC')::date) (bar_start_utc AT TIME ZONE 'UTC')::date AS d,bar_start_utc AS t,open_price AS p,native_minute_bars AS n FROM gold_research_histdata_xau15m_candidate WHERE bar_start_utc>='2026-01-01' AND bar_start_utc<'2026-10-01' AND EXTRACT(ISODOW FROM bar_start_utc AT TIME ZONE 'UTC')<=5 AND (bar_start_utc AT TIME ZONE 'UTC')::time>='09:00:00' AND native_minute_bars=15 ORDER BY (bar_start_utc AT TIME ZONE 'UTC')::date,bar_start_utc;

SELECT (bar_start_utc AT TIME ZONE 'UTC')::date AS d,min(bar_start_utc) AS first_bar,max(bar_start_utc) AS last_bar,count(*) AS n,sum(native_minute_bars) AS minute_count FROM gold_research_histdata_xau15m_candidate WHERE bar_start_utc>='2026-01-01' AND bar_start_utc<'2026-10-14' GROUP BY 1 ORDER BY 1;
